export function block(collection, item, overrides = {}) {
  return {
    id: `${collection}-${item.key || item.title || item.episode || 'story'}`,
    collection,
    sort: overrides.sort || 10,
    slot: overrides.slot || 'main',
    item,
    section: overrides.section || {},
    ...overrides,
  };
}

