export default meta;

function InventorySurface() {
  return (
    <main style={{ padding: 'clamp(32px, 6vw, 88px)' }}>
      <p style={{
        fontFamily: 'var(--mono)',
        fontSize: 10,
        letterSpacing: '0.14em',
        margin: '0 0 12px',
        textTransform: 'uppercase',
